// 365 Bible verses — one for each day of the year
// Curated for encouragement, faith, hope, and daily strength
import { tc } from "@/i18n";


export type PrayerMood = "morning" | "night" | "anxiety" | "strength";

export interface DailyVerse {
  text: string;
  reference: string;
  /** Original English reference, kept as the stable lookup id after localization. */
  refKey?: string;
}

export interface DevotionalCard {
  verse: DailyVerse;
  prayer: string;
  mood: PrayerMood;
  gradient: string;
}

