const moodPrayers: Record<PrayerMood, number[]> = {
  morning: [0, 3, 10, 17, 22, 30, 36, 43, 50, 57, 64, 70, 76, 82, 88, 93, 98],
  night: [5, 7, 15, 25, 35, 44, 55, 65, 72, 80, 87, 95],
  anxiety: [1, 2, 6, 9, 11, 20, 24, 28, 38, 45, 48, 56, 63, 73, 84, 90],
  strength: [4, 8, 12, 14, 18, 21, 31, 34, 40, 47, 52, 58, 61, 68, 78, 85, 91, 96],
};

export function getDevotionalFeed(mood?: PrayerMood, count = 10): DevotionalCard[] {
  const d = new Date();
  const start = new Date(d.getFullYear(), 0, 0);
  const diff = d.getTime() - start.getTime();
  const dayOfYear = Math.floor(diff / (1000 * 60 * 60 * 24));

  const cards: DevotionalCard[] = [];
  const gradients = mood ? moodGradients[mood] : moodGradients.morning;
  const prayerIndices = mood ? moodPrayers[mood] : undefined;

  for (let i = 0; i < count; i++) {
    const vIdx = (dayOfYear + i) % verses.length;
    const pIdx = prayerIndices
      ? prayerIndices[(dayOfYear + i) % prayerIndices.length]
      : (dayOfYear + i) % prayers.length;

    cards.push({
      verse: verses[vIdx],
      prayer: prayers[pIdx],
      mood: mood || (["morning", "night", "anxiety", "strength"] as PrayerMood[])[(dayOfYear + i) % 4],
      gradient: gradients[(dayOfYear + i) % gradients.length],
    });
  }

  return cards;
}

