const prayerDeclarations = [
  "Let Your peace rule my thoughts and steady my heart.",
  "Help me walk in faith today, one step at a time.",
  "Fill me with hope that outlasts every fear.",
  "Teach me to trust You more than my emotions.",
  "Let Your presence be the strength I lean on today.",
  "Give me grace for this moment and courage for the next.",
  "Quiet every anxious voice and remind me You are near.",
  "Align my mind, words, and actions with Your will.",
  "Renew my spirit and help me shine Your love today.",
  "Hold me close and lead me in wisdom and peace.",
  "Be the light that guides my every step today.",
  "Remind me that I am never walking alone.",
  "Anchor my soul in the unshakable truth of who You are.",
  "Let Your joy rise within me, even in the hardest hours.",
  "Make me a vessel of Your grace to everyone I meet.",
  "Cover me with Your mercy from morning until night.",
  "Speak louder than every voice of doubt and fear.",
  "Carry what I cannot carry on my own.",
  "Let Your love flow through me freely and without measure.",
  "Order my steps and direct my heart toward You.",
  "Strengthen what is weak and restore what is broken.",
  "Be my peace when the world around me is loud.",
  "Help me see this day through eyes of gratitude.",
  "Wrap me in Your faithfulness like a familiar coat.",
  "Lead me beside still waters and restore my soul.",
  "Plant Your Word in me deeper than any storm can shake.",
  "Let every breath I take be an offering of praise to You.",
  "Be the still, small voice I cannot ignore today.",
  "Make me brave with the courage that only comes from heaven.",
  "Bind me to Your heart, and never let me wander.",
];

function enrichPrayer(basePrayer: string, index: number): string {
  // Deterministic pairing — each prayer always gets the same declaration
  const dIdx = index % prayerDeclarations.length;
  // Localized copies when a content pack is loaded, English otherwise.
  const base = tc(`p.${index}`) ?? basePrayer;
  const declaration = tc(`pd.${dIdx}`) ?? prayerDeclarations[dIdx];
  const amen = tc("p.amen") ?? " Amen.";

  if (base.includes(amen)) {
    return base.replace(amen, ` ${declaration}${amen}`);
  }
  if (base.includes(" Amen.")) {
    return base.replace(" Amen.", ` ${declaration} Amen.`);
  }

  return `${base} ${declaration}`;
}


export function getDailyPrayerIndex(date?: Date): number {
  const d = date || new Date();
  const start = new Date(d.getFullYear(), 0, 0);
  const diff = d.getTime() - start.getTime();
  const dayOfYear = Math.floor(diff / (1000 * 60 * 60 * 24));
  return dayOfYear % prayers.length;
}

export function getDailyPrayer(date?: Date): string {
  const index = getDailyPrayerIndex(date);
  return enrichPrayer(prayers[index], index);
}

export const PRAYER_COUNT = prayers.length;
